 "content": "def transform(grid):
    # Recolor each connected component of 1s to the color of a congruent non-1 shape.
    # Components are matched by their normalized cell pattern, allowing rotations/reflections.
    from collections import deque
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          col=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
          while q:
            y,x=q.pop(); cells.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              z=(y+dy,x+dx)
              if 0<=z[0]<h and 0<=z[1]<w and z not in seen and grid[z[0]][z[1]]==col:
                seen.add(z); q.append(z)
          comps.append((col,cells))
    def variants(cells):
      outs=set()
      for swap in (False,True):
       for sy in (-1,1):
        for sx in (-1,1):
         pts=[(sy*(x if swap else y),sx*(y if swap else x)) for y,x in cells]
         my=min(y for y,x in pts); mx=min(x for y,x in pts)
         outs.add(tuple(sorted((y-my,x-mx) for y,x in pts)))
      return outs
    pats={}
    for col,cells in comps:
      if col!=1:
        for p in variants(cells): pats.setdefault(p,col)
    out=[row[:] for row in grid]
    for col,cells in comps:
      if col==1:
        match=next((pats[p] for p in variants(cells) if p in pats),None)
        if match is not None:
          for y,x in cells: out[y][x]=match
    return out
